async function request(path:string,body?:any,method='POST'){const r=await fetch('/api/'+path,{method:body===undefined?'GET':method,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let d:any;try{d=await r.json()}catch{throw new Error('Decant could not connect. Please try again.')}if(!r.ok)throw new Error(d.error||'Please try again.');return d}
function Choice({value,onChange,options,label}:{value:string;onChange:(v:string)=>void;options:{value:string;label:string}[];label:string}){return <Select value={value} onValueChange={v=>onChange(String(v))}><SelectTrigger className="choice" aria-label={label}><SelectValue>{options.find(o=>o.value===value)?.label}</SelectValue></SelectTrigger><SelectContent className="choice-menu">{options.map(o=><SelectItem className="choice-item" key={o.value} value={o.value}>{o.label}</SelectItem>)}</SelectContent></Select>}
function Field({label,name,value,onChange,type='text',required=false,min,max,wide=false,readOnly=false}:{label:string;name:string;value:any;onChange:(name:string,v:any)=>void;type?:string;required?:boolean;min?:number;max?:number;wide?:boolean;readOnly?:boolean}){return <label className={wide?'field wide':'field'}>{label}{type==='textarea'?<textarea name={name} value={value??''} onChange={e=>onChange(name,e.target.value)} rows={4} required={required}/>:<input readOnly={readOnly} name={name} type={type} value={value??''} onChange={e=>onChange(name,e.target.value)} required={required} min={min} max={max} step={type==='number'?'any':undefined}/>}</label>}
function Paragraphs({body}:{body:string}){return <div className="prose">{body.split('\n\n').map((p,i)=>{const match=p.match(/https:\/\/[^\s]+/);return <p key={i}>{match?<>{p.slice(0,match.index)}<a href={match[0]} target="_blank" rel="noreferrer">Read the source ↗</a></>:p}</p>})}</div>}
